@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@400;500;600;700&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* Editorial — magazine: Playfair Display, generous whitespace, thin rules, paper tones */
.theme-editorial {
  --bg: oklch(0.975 0.011 85);
  --surface: oklch(0.99 0.006 85);
  --surface-2: oklch(0.955 0.014 82);
  --fg: oklch(0.22 0.014 60);
  --fg-muted: oklch(0.48 0.015 60);
  --accent: oklch(0.45 0.13 30);
  --accent-fg: oklch(0.98 0.008 85);
  --accent-2: oklch(0.55 0.07 150);
  --line: oklch(0.22 0.014 60 / 22%);
  --success: oklch(0.5 0.11 150);
  --warning: oklch(0.68 0.13 75);
  --danger: oklch(0.5 0.17 25);

  --radius: 0rem;
  --radius-sm: 0rem;
  --radius-lg: 0rem;
  --radius-pill: 9999px;

  --shadow-1: 0 1px 0 0 var(--line);
  --shadow-2: 0 10px 30px -22px oklch(0.22 0.014 60 / 55%);
  --shadow-3: 0 24px 60px -34px oklch(0.22 0.014 60 / 60%);
  --glow: none;

  --border-width: 1px;
  --blur-amount: 0px;

  --font-display: "Playfair Display", Georgia, serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  --tracking-display: -0.015em;
  --label-transform: uppercase;
  --label-tracking: 0.2em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-editorial h1,
.theme-editorial h2,
.theme-editorial h3 {
  font-family: var(--font-display);
  font-weight: 500;
  letter-spacing: var(--tracking-display);
  line-height: 1.05;
}

/* signature */
.theme-editorial h1 { font-weight: 500; font-style: italic; }
.theme-editorial h2 { border-top: 1px solid var(--line); padding-top: 0.75rem; }
.theme-editorial ::selection { background: oklch(0.9 0.03 80); }
.theme-editorial h1 { font-size: clamp(3.2rem, 6.5vw, 5.2rem) !important; line-height: 1.02; }
.theme-editorial .label-caps { color: oklch(0.5 0.09 30); }

/* depth */
.theme-editorial thead th { text-transform: uppercase; letter-spacing: var(--label-tracking); font-size: 0.68em; font-weight: 500; color: var(--fg-muted); border-bottom: 1px solid var(--fg); text-align: left; }
.theme-editorial td { border-bottom: 1px solid var(--line); }
.theme-editorial tbody tr:hover { background: var(--surface-2); }
/* physical: editorial hairline fields — no box, just a rule on the baseline */
.theme-editorial input, .theme-editorial select, .theme-editorial textarea { background: transparent; border: 0; border-bottom: 1px solid var(--line); border-radius: 0; }
.theme-editorial input:focus, .theme-editorial select:focus, .theme-editorial textarea:focus { outline: none; border-bottom-color: var(--fg); box-shadow: 0 1px 0 0 var(--fg); }
.theme-editorial a { color: var(--fg); text-decoration-thickness: 1px; text-underline-offset: 4px; text-decoration-color: var(--line); }
.theme-editorial a:hover { color: var(--accent); text-decoration-color: var(--accent); }
.theme-editorial kbd { font-family: var(--font-mono); font-size: 0.8em; padding: 0.1em 0.45em; border: 1px solid var(--line); border-radius: 0; background: var(--surface); }
.theme-editorial blockquote { font-family: var(--font-display); font-style: italic; font-size: 1.15em; border-left: 2px solid var(--accent); padding-left: 1.25rem; }
.theme-editorial ::-webkit-scrollbar { width: 8px; height: 8px; }
.theme-editorial ::-webkit-scrollbar-track { background: transparent; }
.theme-editorial ::-webkit-scrollbar-thumb { background: oklch(0.22 0.014 60 / 30%); border-radius: 0; }
.theme-editorial ::-webkit-scrollbar-thumb:hover { background: var(--fg); }
.theme-editorial .themed-border { border-top: 3px solid var(--fg); border-bottom: 1px solid var(--fg); }
.theme-editorial button:active { transform: translateY(1px); }

/* alt mode: evening edition — warm lamplight paper inverted, masthead red glows */
.theme-editorial.alt-mode {
  --bg: oklch(0.145 0.011 85.0);
  --surface: oklch(0.185 0.011 85.0);
  --surface-2: oklch(0.225 0.011 85.0);
  --fg: oklch(0.94 0.012 85);
  --fg-muted: oklch(0.7 0.02 80);
  --accent: oklch(0.68 0.13 30);
  --accent-fg: oklch(0.16 0.01 60);
  --line: oklch(0.94 0.012 85 / 18%);
  --shadow-1: 0 1px 0 0 var(--line);
  --shadow-2: 0 10px 30px -22px oklch(0 0 0 / 70%);
  --shadow-3: 0 24px 60px -34px oklch(0 0 0 / 75%);
}
.theme-editorial.alt-mode thead th, .theme-editorial.alt-mode .themed-border { border-color: var(--fg); }
.theme-editorial.alt-mode a { color: var(--fg); }
.theme-editorial.alt-mode a:hover { color: var(--accent); }
.theme-editorial.alt-mode ::selection { background: oklch(0.4 0.06 60); color: var(--fg); }
.theme-editorial.alt-mode .label-caps { color: oklch(0.72 0.1 35); }
.theme-editorial.alt-mode ::-webkit-scrollbar-thumb { background: oklch(0.94 0.012 85 / 30%); }
.theme-editorial.alt-mode input:focus, .theme-editorial.alt-mode select:focus, .theme-editorial.alt-mode textarea:focus { border-bottom-color: var(--fg); box-shadow: 0 1px 0 0 var(--fg); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
